using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using StockFlow.Data;
using StockFlow.Models;
namespace StockFlow.Controllers; [Authorize(Roles = "Admin,Manager,Procurement,Viewer,StockClerk")] public class SuppliersController(ApplicationDbContext db) : Controller { public async Task<IActionResult> Index(string? q) { var x = db.Suppliers.AsQueryable(); if (!string.IsNullOrWhiteSpace(q)) x = x.Where(s => s.Name.Contains(q) || (s.Email != null && s.Email.Contains(q))); ViewBag.Query = q; return View(await x.OrderBy(s => s.Name).ToListAsync()); } [Authorize(Roles = "Admin,Manager,Procurement")] public IActionResult Create() => View(new Supplier()); [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,Procurement")] public async Task<IActionResult> Create(Supplier s) { if (!ModelState.IsValid) return View(s); db.Suppliers.Add(s); await db.SaveChangesAsync(); TempData["Success"] = "Supplier created."; return RedirectToAction(nameof(Index)); } [Authorize(Roles = "Admin,Manager,Procurement")] public async Task<IActionResult> Edit(int id) { var s = await db.Suppliers.FindAsync(id); return s == null ? NotFound() : View(s); } [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,Procurement")] public async Task<IActionResult> Edit(int id, Supplier s) { if (id != s.Id) return BadRequest(); if (!ModelState.IsValid) return View(s); db.Update(s); await db.SaveChangesAsync(); TempData["Success"] = "Supplier updated."; return RedirectToAction(nameof(Index)); } }
